import{_ as o,C as i,o as t,c as l,j as s,a,b as d,w as r,E as u,a2 as g,a3 as c}from"./chunks/framework.pb1iZPmZ.js";const w=JSON.parse('{"title":"14.7 System Design: Messaging, Queues & Async Processing","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.7-messaging-queues.md","filePath":"system-design/14.7-messaging-queues.md"}'),h={name:"system-design/14.7-messaging-queues.md"};function m(p,e,y,f,b,x){const n=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=s("h1",{id:"_14-7-system-design-messaging-queues-async-processing",tabindex:"-1"},[a("14.7 System Design: Messaging, Queues & Async Processing "),s("a",{class:"header-anchor",href:"#_14-7-system-design-messaging-queues-async-processing","aria-label":'Permalink to "14.7 System Design: Messaging, Queues & Async Processing"'},"​")],-1)),(t(),d(g,null,{default:r(()=>[u(n,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Synchronous%5B%22Synchronous%20User%20Flow%20(%3C50ms)%22%5D%0A%20%20%20%20%20%20%20%20User%5BUser%20Registration%20%2F%20Login%5D%20--%3E%20Server%5BExpress%20App%5D%0A%20%20%20%20%20%20%20%20Server%20--%3E%7CImmediate%20302%20Redirect%7C%20User%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20AsyncQueue%5B%22Asynchronous%20Job%20Queue%20(BullMQ%20%2F%20Redis)%22%5D%0A%20%20%20%20%20%20%20%20Server%20--%3E%7CEnqueue%20Job%3A%20'send-welcome-email'%7C%20RedisQueue%5B(%22Redis%20Job%20Queue%22)%5D%0A%20%20%20%20%20%20%20%20RedisQueue%20--%3E%20Worker%5BBackground%20Worker%20Process%5D%0A%20%20%20%20%20%20%20%20Worker%20--%3E%7CSMTP%20API%7C%20MailProvider%5BSendGrid%20%2F%20Hospital%20SMTP%5D%0A%20%20%20%20%20%20%20%20Worker%20--%3E%7CAudit%20Log%7C%20AuditDB%5B(%22Compliance%20Audit%20DB%22)%5D%0A%20%20%20%20end%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=c('<hr><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Asynchronous messaging and queue systems decouple fast user-facing HTTP request-response cycles from slow, error-prone, or heavy background tasks (such as sending verification emails, auditing login events, generating PDF reports, or calling external webhooks).</p><hr><h2 id="_2-whether-and-how-this-project-uses-it" tabindex="-1">2. Whether and How THIS Project Uses It <a class="header-anchor" href="#_2-whether-and-how-this-project-uses-it" aria-label="Permalink to &quot;2. Whether and How THIS Project Uses It&quot;">​</a></h2><p>In the current code, asynchronous message queues are <strong>Not Used</strong>. All operations—such as saving users, checking duplicates, and destroying sessions—execute synchronously within the HTTP request cycle. This was an acceptable decision for an MVP authentication portal with no external email or SMS integrations [CONFIRM WITH DEVELOPER].</p><hr><h2 id="_3-queue-stream-technologies-comparison" tabindex="-1">3. Queue &amp; Stream Technologies Comparison <a class="header-anchor" href="#_3-queue-stream-technologies-comparison" aria-label="Permalink to &quot;3. Queue &amp; Stream Technologies Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Technology</th><th style="text-align:left;">Paradigm</th><th style="text-align:left;">Message Ordering</th><th style="text-align:left;">Throughput</th><th style="text-align:left;">Persistence</th><th style="text-align:left;">Fit for This Auth Portal</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>BullMQ (Redis-backed)</strong></td><td style="text-align:left;"><strong>In-Memory Message Queue</strong></td><td style="text-align:left;"><strong>FIFO per queue</strong></td><td style="text-align:left;"><strong>~10,000–50,000 ops/sec</strong></td><td style="text-align:left;"><strong>Redis AOF / RDB</strong></td><td style="text-align:left;"><strong>Optimal for Node.js background tasks (emails, audits)</strong></td></tr><tr><td style="text-align:left;"><strong>RabbitMQ</strong></td><td style="text-align:left;">AMQP Message Broker</td><td style="text-align:left;">Strict FIFO per queue</td><td style="text-align:left;">~20,000–40,000 msg/sec</td><td style="text-align:left;">Disk &amp; Memory</td><td style="text-align:left;">Heavy broker setup; overkill for basic background jobs</td></tr><tr><td style="text-align:left;"><strong>Apache Kafka</strong></td><td style="text-align:left;">Distributed Event Log</td><td style="text-align:left;">Partition-ordered</td><td style="text-align:left;">~1,000,000+ msg/sec</td><td style="text-align:left;">Distributed disk commit log</td><td style="text-align:left;">Massive architectural overhead</td></tr><tr><td style="text-align:left;"><strong>AWS SQS</strong></td><td style="text-align:left;">Managed Cloud Queue</td><td style="text-align:left;">Standard (Best-effort) / FIFO</td><td style="text-align:left;">High</td><td style="text-align:left;">Managed by AWS</td><td style="text-align:left;">Vendor-locked; introduces network latency</td></tr></tbody></table><hr><h2 id="_4-delivery-semantics-failure-handling" tabindex="-1">4. Delivery Semantics &amp; Failure Handling <a class="header-anchor" href="#_4-delivery-semantics-failure-handling" aria-label="Permalink to &quot;4. Delivery Semantics &amp; Failure Handling&quot;">​</a></h2><ol><li><strong>At-Least-Once Delivery</strong>: The queue guarantees the message is delivered, but network retries might cause duplicate executions. Background consumers must be <strong>idempotent</strong> (e.g. checking whether a welcome email has already been recorded in a <code>dispatched_emails</code> collection before sending).</li><li><strong>Dead-Letter Queue (DLQ)</strong>: If a worker fails to process an email job after 5 exponential backoff retries (e.g. SMTP server down), the job is routed to a DLQ for developer inspection without clogging the primary queue.</li></ol><hr><h2 id="_5-what-breaks-first-at-scale" tabindex="-1">5. What Breaks First at Scale <a class="header-anchor" href="#_5-what-breaks-first-at-scale" aria-label="Permalink to &quot;5. What Breaks First at Scale&quot;">​</a></h2><ul><li><strong>10x Load</strong>: Synchronous operations hold up fine.</li><li><strong>100x Load</strong>: If an external email or SMS service is added synchronously to <code>POST /signup</code>, third-party network timeouts will freeze the user&#39;s browser for 10–30 seconds.</li><li><strong>1000x Load</strong>: Node process memory exhausts under concurrent unqueued background promises.</li></ul><hr><h2 id="_6-senior-engineering-improvements" tabindex="-1">6. Senior Engineering Improvements <a class="header-anchor" href="#_6-senior-engineering-improvements" aria-label="Permalink to &quot;6. Senior Engineering Improvements&quot;">​</a></h2><p>Add <strong>BullMQ</strong> with Redis:</p><ol><li>When a clinician signs up, immediately respond with the 302 redirect.</li><li>Push a background job <code>{ type: &#39;AUDIT_LOGIN&#39;, userId: user._id, ip: req.ip, timestamp: Date.now() }</code> to BullMQ.</li><li>A separate worker process processes the queue asynchronously without adding a single millisecond to the user&#39;s HTTP response time.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Right now, all operations in the portal execute synchronously within the HTTP request. As we add clinical welcome emails, multi-factor SMS codes, or HIPAA audit logging, executing those synchronously would hurt latency. I would introduce BullMQ backed by Redis to offload email dispatching and audit recording to background worker processes, keeping HTTP response times under 50 milliseconds.&quot;</p></blockquote>',22))])}const S=o(h,[["render",m]]);export{w as __pageData,S as default};
